ALTER TABLE registration_sessions MODIFY stage ENUM('story','audience','choice') NOT NULL DEFAULT 'story';
ALTER TABLE characters ADD COLUMN constitution_growth DECIMAL(4,1) NOT NULL DEFAULT 0, ADD COLUMN spirit_growth DECIMAL(4,1) NOT NULL DEFAULT 0, ADD COLUMN strength_growth DECIMAL(4,1) NOT NULL DEFAULT 0, ADD COLUMN intelligence_growth DECIMAL(4,1) NOT NULL DEFAULT 0, ADD COLUMN agility_growth DECIMAL(4,1) NOT NULL DEFAULT 0, ADD COLUMN perception_growth DECIMAL(4,1) NOT NULL DEFAULT 0, ADD COLUMN adventurer_registered TINYINT(1) NOT NULL DEFAULT 0;
CREATE TABLE player_equipment (character_id BIGINT UNSIGNED NOT NULL, slot ENUM('weapon') NOT NULL, item_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY (character_id, slot), UNIQUE KEY uk_equipment_item (character_id, item_id), CONSTRAINT fk_equipment_character FOREIGN KEY (character_id) REFERENCES characters(id) ON DELETE CASCADE, CONSTRAINT fk_equipment_item FOREIGN KEY (item_id) REFERENCES item_definitions(id)) ENGINE=InnoDB;
CREATE TABLE player_blessings (character_id BIGINT UNSIGNED NOT NULL, code VARCHAR(64) NOT NULL, PRIMARY KEY (character_id), CONSTRAINT fk_blessing_character FOREIGN KEY (character_id) REFERENCES characters(id) ON DELETE CASCADE) ENGINE=InnoDB;
